def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()

def decode(rel):
    return gzip.decompress(base64.b64decode(BLOBS[rel]))

def fail(msg):
    raise SystemExit("26490 FAIL: " + msg)

def mirror_index(value, size):
    if size <= 1:
        return 0
    period = 2 * (size - 1)
    wrapped = value % period
    return wrapped if wrapped < size else period - wrapped

def validate_display_gain_math():
    # Reproduce real 26489 logs, proving the large scalar is the percentile-derived display gain.
    cases = [
        # p50, p90, p99/highlight occupancy reduction, expected final
        (0.0039081583, 0.025891548, 0.998025, 9.412339),
        (0.0058622,    0.0141671,   0.96905,  10.087743),
    ]
    for p50,p90,reduction,expected in cases:
        gain50 = 0.050 / max(p50, 1e-12)
        gain90 = 0.180 / max(p90, 1e-12)
        scene = math.sqrt(max(1.0,gain50)*max(1.0,gain90))
        value = min(16.0, max(1.0, scene*reduction))
        # Logs/rounded source telemetry are not exact to every decimal; 0.003 is ample to verify equation.
        if abs(value-expected) > 0.003:
            fail(f"display gain model mismatch got={value} expected~={expected}")
    print("26490 DISPLAY-GAIN REAL-LOG MATH PASS twoCases=true sensorDomainUnaffected=true")

def validate_short_ratio_math():
    normal_exp=8_333_000.0; short_exp=2_777_667.0; iso=104.0
    ratio=(normal_exp*iso)/(short_exp*iso)
    ev=math.log(ratio,2.0)
    if abs(ratio-2.999879) > 0.002 or abs(ev-1.5849) > 0.002:
        fail(f"short ratio math got ratio={ratio} ev={ev}")
    print(f"26490 SHORT RADIOMETRY MATH PASS shortToNormalScale={ratio:.6f} headroomEv={ev:.6f}")

def validate_short_alignment_math():
    # LK brightness constancy requires the differently exposed short guide to be mapped
    # into the normal-reference radiance domain. The physical short CFA itself stays unchanged.
    normal=0.42; ratio=3.0; reference_scale=1.0; wb=1.37
    short_physical=normal/ratio
    ref_guide=normal*reference_scale*wb
    short_alignment_guide=short_physical*(ratio*reference_scale)*wb
    if abs(ref_guide-short_alignment_guide) > 1e-7:
        fail(f"short alignment radiometry mismatch ref={ref_guide} short={short_alignment_guide}")
    if abs(short_physical-normal/ratio) > 1e-12:
        fail("physical short CFA was modified by alignment normalization model")
    print("26490 SHORT ALIGNMENT RADIOMETRY PASS brightnessConstancy=true physicalShortUntouched=true")

def validate_short_flow_math():
    # Reuse the established short-highlight confidence mapping from mfsr_flow_expand Z/W.
    def smoothstep(a,b,x):
        t=max(0.0,min(1.0,(x-a)/(b-a)))
        return t*t*(3.0-2.0*t)
    minimum=0.30
    stable=(1.0-0.0)*math.exp(-80.0*0.0)
    ambiguous=(1.0-0.0)*math.exp(-80.0*0.020)
    cancelled=(1.0-1.0)*math.exp(-80.0*0.0)
    mid=0.55
    if stable < 0.999999 or ambiguous >= minimum or cancelled != 0.0:
        fail(f"short flow confidence model invalid stable={stable} ambiguous={ambiguous} cancelled={cancelled}")
    if abs(smoothstep(minimum,0.80,mid)-0.5) > 1e-9:
        fail("short flow graded gate midpoint invalid")
    print("26490 SHORT FLOW RELIABILITY MATH PASS stable=1 ambiguousRejected=true cancelledRejected=true graded=true minimum=0.30")

def validate_censored_highlight_math():
    # Old 26489 bug: display gain was incorrectly used as sensor white, disabling 0.985 clipping.
    def smoothstep(a,b,x):
        t=max(0.0,min(1.0,(x-a)/(b-a)))
        return t*t*(3.0-2.0*t)
    old_mask=smoothstep(0.985,1.0,1.0/9.412339)
    new_mask=smoothstep(0.985,1.0,1.0)
    if old_mask != 0.0 or abs(new_mask-1.0)>1e-9:
        fail(f"RCD clip-domain model mismatch old={old_mask} new={new_mask}")
    # A valid 1/3-exposure observation at 0.40 maps to 1.20 normal-domain radiance.
    # The clipped normal is a lower bound: short recovery may extend it, never darken it.
    normal=1.0; short=0.40; scale=3.0
    recovered=max(normal,short*scale)
    if abs(recovered-1.20)>1e-9 or recovered < normal:
        fail(f"censored lower-bound recovery mismatch {recovered}")
    # bjzhou-style opposed highlight reconstruction also preserves its input as a lower bound:
    # return max(base, opposedEstimate). Therefore an extended short measurement cannot be
    # reduced by the later RCD stage even though it remains physically classified as clipped.
    opposed_candidate=1.08
    rcd_reconstructed=max(recovered,opposed_candidate)
    if rcd_reconstructed < recovered:
        fail("RCD would reduce measured short radiance")
    # If short evidence contains no additional headroom, the clipped normal remains 1.0 and the
    # ordinary deterministic RCD censored-site reconstruction remains eligible.
    weak=max(normal,0.30*scale)
    weak_clip=smoothstep(0.985,1.0,weak)
    if abs(weak-normal)>1e-9 or abs(weak_clip-1.0)>1e-9:
        fail("unrecovered clipped-site fallback model invalid")
    print("26490 CENSORED-HIGHLIGHT MATH PASS oldDisplayAsWhiteMask=0 physicalWhiteMask=1 lowerBound=true shortMeasuredLowerBoundSurvivesRcd=true unresolvedStillRcdEligible=true")

def validate_short_identity_model():
    short_ts=1_414_607_384_114_145
    nearby=[short_ts-33_333_333,short_ts-2_000_000,short_ts+2_000_000,short_ts+33_333_333]
    if any(x==short_ts for x in nearby): fail("identity test fixture")
    staged=[]
    for ts in [short_ts-100_000_000,short_ts-66_666_666,short_ts-33_333_333,short_ts-10_000_000,short_ts]:
        while len(staged)>=4: staged.pop(0)
        staged.append(ts)
    selected=[x for x in staged if x==short_ts]
    if selected != [short_ts]: fail("exact short timestamp model")
    print("26490 SHORT IDENTITY MODEL PASS exactTimestamp=true nearestFallback=false newestFour=true")

def validate_mirror_halo():
    # RCD output margin=9 and PPG reaches +/-4. Band core=256, halo=12.
    margin=9; radius=4; core=256; halo=12
    if halo < margin+1: fail("RCD halo too small")
    for width,height in [(3072,4096),(4080,3072),(4000,3000),(2048,1536),(256,258)]:
        for core_y in range(0,height,core):
            rows=min(core,height-core_y)
            top=max(0,core_y-halo); bottom=min(height,core_y+rows+halo)
            for gy in range(core_y,core_y+rows):
                # Only true top/bottom photo borders use recursive PPG due y; x reflection is in-band width.
                if not (gy<margin or gy+margin>=height): continue
                for dy in range(-radius,radius+1):
                    sy=mirror_index(gy+dy,height)
                    if not (top<=sy<bottom):
                        fail(f"mirrored PPG y escaped band size={width}x{height} coreY={core_y} gy={gy} dy={dy} sy={sy} band={top}:{bottom}")
    print("26490 RCD MIRROR/HALO MATH PASS allFourEdges=true margin=9 radius=4 halo=12")

def validate_post(root):
    root=Path(root)
    for rel,expected in POST.items():
        p=root/rel
        if not p.is_file(): fail("missing post file "+rel)
        got=sha(p)
        if got!=expected: fail(f"post hash {rel}={got} expected={expected}")

    cap=(root/CAPTURE).read_text()
    frame=(root/FRAME).read_text()
    display=(root/DISPLAY).read_text()
    rcd=(root/RCD_HOST).read_text()
    render=(root/RENDER).read_text()
    hdrx=(root/HDRX).read_text()
    recon=(root/RECON).read_text()
    merger=(root/MERGER).read_text()
    params=(root/PARAMS).read_text()
    rcdw=(root/RCD_WRITE).read_text()
    rcdp=(root/RCD_POPULATE).read_text()
    shortrec=(root/SHORT_RECOVER).read_text()

    # --- Exposure-domain ownership ---
    required=[
        (params,"IRIS_26490_MOTION_SENSOR_DOMAIN_SENTINEL"),
        (params,"motionCanonicalExposureGain = 1.0f"),
        (params,"motionV2DisplayGain = 1.0f"),
        (recon,"IRIS_26490_EXPLICIT_DISPLAY_GAIN_OWNER"),
        (recon,"parameters.motionCanonicalExposureGain = 1.0f"),
        (recon,"parameters.motionV2DisplayGain ="),
        (recon,"MotionV2Merger.computeDisplayGain("),
        (merger,"IRIS_26490_EXPLICIT_DISPLAY_DOMAIN"),
        (display,"motionV2DisplayGain"),
        (rcd,"IRIS_26490_RCD_EXPOSURE_DOMAIN"),
        (rcd,'final float iris26490PhysicalSensorWhite = 1.0f'),
        (rcd,'glProg.setVar("sensorClipLevel", iris26490PhysicalSensorWhite)'),
        (render,"postDisplaySensorWhite"),
        (render,"motionV2DisplayGain"),
        (hdrx,"IRIS_26490_MOTION_V2_DOMAIN_OWNERSHIP"),
    ]
    for text,needle in required:
        if needle not in text: fail("missing exposure-domain contract "+needle)
    if "computeReferenceGain(" in merger or "computeReferenceGain(" in recon:
        fail("ambiguous computeReferenceGain survived active owner")
    # Display gain may be used only by explicit post-RCD display/tone/log owner files among changed active owners.
    if "motionV2DisplayGain" in rcd and "displayGain=" not in rcd:
        fail("RCD display gain used beyond diagnostic log")
    if "motionCanonicalExposureGain" in display or "motionCanonicalExposureGain" in rcd or "motionCanonicalExposureGain" in render:
        fail("legacy ambiguous gain survived active post graph")
    if "final float canonicalGain = 1.0f;" not in recon:
        fail("Wronski canonical gain not unity")
    # Ensure sensorClipLevel cannot be set to display/canonical gain in RCD host.
    rcd_sensor_lines=[ln.strip() for ln in rcd.splitlines() if 'setVar("sensorClipLevel"' in ln]
    if rcd_sensor_lines != ['glProg.setVar("sensorClipLevel", iris26490PhysicalSensorWhite);']:
        fail("unexpected RCD sensorClipLevel binding: "+repr(rcd_sensor_lines))
    for needle in [
        "IRIS_26490_SHORT_RECOVERY_EXECUTED_STATE_OWNER",
        "motionV2ShortHighlightRecoveryExecuted = false",
    ]:
        if needle not in params: fail("missing short recovery diagnostic state owner "+needle)
    if "shortExtendedRadiancePresent" in rcd or "shortExtendedRadiancePresent" in rcdp:
        fail("coarse global short state is still driving RCD pixel math")
    if "motionV2ShortHighlightRecoveryExecuted" not in rcd or "shortRecoveryExecuted=" not in rcd:
        fail("RCD short recovery diagnostic log missing")
    for needle in [
        "IRIS_26490_PHYSICAL_CENSORING_WITH_LOWER_BOUND",
        "float clipMix = smoothstep(highlightThreshold, 1.0, physical);",
        "return max(base, opposed * opposed * opposed);",
    ]:
        if needle not in rcdp: fail("RCD physical censor/lower-bound contract missing "+needle)

    # --- Short capture exact identity and lifecycle ---
    for needle in [
        "IRIS_26490_SHORT_CAPTURE_STARTED_IDENTITY",
        "IRIS_26490_EXACT_SHORT_RAW_NEVER_ENTERS_NORMAL_RING",
        "IRIS_26490_SHORT_TICKET_SURVIVES_NORMAL_BATCH_FREEZE",
        "IRIS_26490_GENERATION_OWNED_SHORT_TICKET_LIFETIME",
        "IRIS_26490_NEWEST_FOUR_PRE_RESULT_RAW_COPIES",
        "expectedTimestampNs()",
        "iris26490RawTimestamp == iris26490ExpectedShortTimestamp",
        "im.getTimestamp() == ticket.resultTimestampNs",
        "frame.timestamp == timestampNs",
    ]:
        if needle not in cap: fail("missing short identity/lifetime contract "+needle)
    if "MOTION_26481_SHORT_TIMESTAMP_TOLERANCE_NS" in cap:
        fail("fuzzy short tolerance survived")
    # No nearest/tolerance match in active ticket functions.
    if "Math.abs(im.getTimestamp() - ticket.resultTimestampNs)" in cap:
        fail("nearest short ring match survived")
    # finalizeMotionZslCapture must not clear ticket near freeze boundary.
    fs=cap.index("private void finalizeMotionZslCapture()")
    fe=cap.index("private void captureStillPicture()",fs)
    fbody=cap[fs:fe]
    freeze_marker=fbody.index("IRIS_26490_SHORT_TICKET_SURVIVES_NORMAL_BATCH_FREEZE")
    if "mMotion26486CaptureShortTicket = null" in fbody[:freeze_marker+500]:
        fail("short ticket detached at normal batch freeze")

    # --- Per-frame radiometry ---
    for needle in ["motionV2BlackLevel", "motionV2BlackLevelValid", "motionV2WhiteLevel", "motionV2WhiteLevelValid"]:
        if needle not in frame: fail("missing per-frame radiometry field "+needle)
    for needle in ["SENSOR_DYNAMIC_BLACK_LEVEL","SENSOR_BLACK_LEVEL_PATTERN","SENSOR_DYNAMIC_WHITE_LEVEL","SENSOR_INFO_WHITE_LEVEL"]:
        if needle not in cap: fail("missing timestamp-owned calibration source "+needle)
    for needle in ["iris26490ShortBlack","iris26490ShortWhite","shortToNormalScale","IRIS_26490_BENTO_SHORT_SENSOR_DOMAIN_BAYER_RECOVERY",
                   "IRIS_26490_SHORT_ALIGNMENT_RADIOMETRIC_NORMALIZATION",
                   "iris26490ShortAlignmentScale=shortToNormalScale*iris26487ReferenceExposureScale",
                   'glProg.setVar("wbG",iris26490ShortAlignmentScale)',
                   "parameters.motionV2ShortHighlightRecoveryExecuted = true"]:
        if needle not in recon: fail("missing short radiometric/recovery owner "+needle)
    for needle in [
        "IRIS_26490_CENSORED_NORMAL_IS_LOWER_BOUND",
        "vec4 recoveredEstimate = shortSensor * shortToNormalScale * referenceExposureScale",
        "vec4 recovered = max(normal, recoveredEstimate)",
    ]:
        if needle not in shortrec: fail("short censored lower-bound contract missing "+needle)
    for needle in [
        "IRIS_26490_SHORT_FLOW_RELIABILITY_GATE",
        "uniform float minimumFlowConfidence",
        "float flowConfidence = (1.0 - cancelled) * exp(-80.0 * variation)",
        "float flowGate = smoothstep(minimumFlowConfidence, 0.80, flowConfidence)",
        "flowConfidence < minimumFlowConfidence",
        "vec4 useShort = normalClip * shortSafe * flowGate",
    ]:
        if needle not in shortrec: fail("short flow reliability contract missing "+needle)
    for needle in [
        "IRIS_26490_SHORT_FLOW_RELIABILITY_HOST",
        'glProg.setVar("minimumFlowConfidence",0.30f)',
    ]:
        if needle not in recon: fail("short flow reliability host contract missing "+needle)

    # --- Border semantics ---
    for needle in [
        "IRIS_26490_BJZHOU_RCD_PHOTO_BORDER_MIRROR_1TO1",
        "int mirrorIndex(int value,int size)",
        "ivec2 mirrorLocal(ivec2 p)",
        "bool boundary=gp.x<9||gp.y<9||gp.x+9>=rawSize.x||gp.y+9>=rawSize.y;",
        "if(boundary) rgb=ppg(lp);",
    ]:
        if needle not in rcdw: fail("missing RCD mirror/border contract "+needle)
    if "clampLocal" in rcdw: fail("clamp-based virtual PPG center survived")

    validate_display_gain_math()
    validate_short_ratio_math()
    validate_short_alignment_math()
    validate_short_flow_math()
    validate_censored_highlight_math()
    validate_short_identity_model()
    validate_mirror_halo()
    print("26490 REVISED V3 SOURCE VALIDATION PASS exposureDomainSplit=true shortExact=true shortLowerBoundPreservedThroughRcd=true shortFlowReliability=true coarseShortPixelState=false perFrameRadiometry=true mirrorPpg=true")

def apply(root):
    root=Path(root)
    for rel,expected in PRE.items():
        p=root/rel
        if not p.is_file(): fail("missing pre file "+rel)
        got=sha(p)
        if got!=expected: fail(f"pre hash {rel}={got} expected={expected}")
    for rel in sorted(BLOBS):
        p=root/rel
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_bytes(decode(rel))
    validate_post(root)
    print(f"26490 V3 transform PASS files={len(BLOBS)}")

def self_test():
    for rel in BLOBS:
        got=hashlib.sha256(decode(rel)).hexdigest()
        if got!=POST[rel]: fail(f"embedded blob {rel}={got} expected={POST[rel]}")
    validate_display_gain_math(); validate_short_ratio_math(); validate_short_alignment_math(); validate_short_flow_math(); validate_censored_highlight_math(); validate_short_identity_model(); validate_mirror_halo()
    print(f"26490 V3 transform self-test PASS embeddedFiles={len(BLOBS)}")

if __name__ == '__main__':
    if len(sys.argv)==2 and sys.argv[1]=='--self-test': self_test()
    else: apply(Path(sys.argv[1]) if len(sys.argv)>1 else Path('.'))
